-- ===== 20261108000001_reports.sql =====
-- Phase 9: sales and order reports for admins. Read-only, additive.
-- "Sales" excludes cancelled, returned and refunded orders. Dates are Bangladesh time (Asia/Dhaka).
create or replace function public.admin_sales_report(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_from timestamptz;
  v_to timestamptz;
  r jsonb;
begin
  if not public.has_any_role('super_admin', 'admin') then raise exception 'Not authorised'; end if;
  if p_from is null or p_to is null or p_to < p_from then raise exception 'Choose a valid date range'; end if;
  if p_to - p_from > 366 then raise exception 'Choose a range of at most one year'; end if;
  v_from := (p_from::timestamp) at time zone 'Asia/Dhaka';
  v_to := ((p_to + 1)::timestamp) at time zone 'Asia/Dhaka';

  select jsonb_build_object(
    'summary', (select jsonb_build_object(
        'orders', count(*),
        'sales', coalesce(sum(total) filter (where status not in ('cancelled', 'returned', 'refunded')), 0),
        'sales_orders', count(*) filter (where status not in ('cancelled', 'returned', 'refunded')),
        'delivered_sales', coalesce(sum(total) filter (where status = 'delivered'), 0),
        'discounts', coalesce(sum(discount_total) filter (where status not in ('cancelled', 'returned', 'refunded')), 0),
        'delivery_charges', coalesce(sum(delivery_charge) filter (where status not in ('cancelled', 'returned', 'refunded')), 0),
        'cancelled', count(*) filter (where status = 'cancelled'),
        'returned', count(*) filter (where status in ('returned', 'refunded')))
      from public.orders where placed_at >= v_from and placed_at < v_to),
    'advance_verified', (select coalesce(sum(p.amount), 0) from public.payments p join public.orders o on o.id = p.order_id
        where p.status = 'verified' and o.placed_at >= v_from and o.placed_at < v_to),
    'daily', (select coalesce(jsonb_agg(jsonb_build_object('date', d::date,
        'orders', (select count(*) from public.orders o where o.placed_at >= (d::date::timestamp) at time zone 'Asia/Dhaka' and o.placed_at < ((d::date + 1)::timestamp) at time zone 'Asia/Dhaka'),
        'sales', (select coalesce(sum(o.total), 0) from public.orders o where o.placed_at >= (d::date::timestamp) at time zone 'Asia/Dhaka' and o.placed_at < ((d::date + 1)::timestamp) at time zone 'Asia/Dhaka' and o.status not in ('cancelled', 'returned', 'refunded'))
      ) order by d), '[]'::jsonb) from generate_series(p_from, p_to, interval '1 day') d),
    'by_status', (select coalesce(jsonb_agg(jsonb_build_object('status', status, 'orders', n) order by n desc), '[]'::jsonb)
        from (select status, count(*) n from public.orders where placed_at >= v_from and placed_at < v_to group by status) s),
    'products', (select coalesce(jsonb_agg(t), '[]'::jsonb) from (
        select oi.product_name as name, sum(oi.quantity)::int as units, sum(oi.line_total) as sales
        from public.order_items oi join public.orders o on o.id = oi.order_id
        where o.placed_at >= v_from and o.placed_at < v_to and o.status not in ('cancelled', 'returned', 'refunded')
        group by oi.product_name order by units desc, sales desc, name limit 50) t),
    'districts', (select coalesce(jsonb_agg(t), '[]'::jsonb) from (
        select district, count(*) as orders, sum(total) as sales from public.orders
        where placed_at >= v_from and placed_at < v_to and status not in ('cancelled', 'returned', 'refunded')
        group by district order by orders desc, district limit 30) t),
    'coupons', (select coalesce(jsonb_agg(t), '[]'::jsonb) from (
        select coupon_code as code, count(*) as uses, sum(discount_total) as discount from public.orders
        where placed_at >= v_from and placed_at < v_to and coupon_code is not null and status not in ('cancelled', 'returned', 'refunded')
        group by coupon_code order by uses desc, code limit 30) t)
  ) into r;
  return r;
end
$$;

revoke all on function public.admin_sales_report(date, date) from public, anon;
grant execute on function public.admin_sales_report(date, date) to authenticated;

-- ===== 20261109000001_hardening.sql =====
-- Phase 10: security hardening. Additive; no data is changed.
--  1. throttling for public lookups that could be guessed at (order tracking, coupon codes)
--  2. anonymous visitors lose table privileges they never needed (row-level security stays as the second lock)
--  3. trigger / internal functions can no longer be called as RPC

-- ---------- 1. throttling ----------
create table if not exists public.rate_limits (
  key text primary key,
  window_start timestamptz not null default now(),
  hits integer not null default 0
);
alter table public.rate_limits enable row level security; -- no policies: only the definer functions below touch it
revoke all on public.rate_limits from public, anon, authenticated;

create or replace function public._client_ip()
returns text
language sql
stable
set search_path = ''
as $$
  select coalesce(nullif(trim(split_part(coalesce((nullif(current_setting('request.headers', true), '')::json) ->> 'x-forwarded-for', ''), ',', 1)), ''), 'unknown');
$$;

-- Counts one hit for p_key; raises once p_limit hits happen inside the window.
create or replace function public._throttle(p_key text, p_limit integer, p_window_seconds integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_hits integer;
begin
  if random() < 0.02 then
    delete from public.rate_limits where window_start < now() - interval '1 day';
  end if;
  insert into public.rate_limits as r (key, window_start, hits) values (left(p_key, 200), now(), 1)
  on conflict (key) do update
    set hits = case when r.window_start < now() - make_interval(secs => p_window_seconds) then 1 else r.hits + 1 end,
        window_start = case when r.window_start < now() - make_interval(secs => p_window_seconds) then now() else r.window_start end
  returning hits into v_hits;
  if v_hits > p_limit then
    raise exception 'Too many attempts. Please wait a few minutes and try again.';
  end if;
end
$$;
revoke all on function public._throttle(text, integer, integer) from public, anon, authenticated;
revoke all on function public._client_ip() from public, anon, authenticated;

-- order tracking: per visitor and per order number, so neither one browser nor many can guess phone numbers
create or replace function public.track_order(p_order_number text, p_phone text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  o public.orders;
  v_phone text := regexp_replace(coalesce(p_phone, ''), '^(\+?88)', '');
  v_num text := upper(trim(coalesce(p_order_number, '')));
begin
  perform public._throttle('track:ip:' || public._client_ip(), 30, 600);
  perform public._throttle('track:order:' || v_num, 10, 600);
  select * into o from public.orders where order_number = v_num and phone = v_phone;
  -- A miss returns null instead of raising: an exception would roll back this call's throttle count,
  -- so failed guesses would never be counted.
  if not found then return null; end if;
  return jsonb_build_object(
    'order_id', o.id, 'order_number', o.order_number, 'status', o.status, 'placed_at', o.placed_at,
    'district', o.district, 'area', o.area,
    'subtotal', o.subtotal, 'discount_total', o.discount_total, 'delivery_charge', o.delivery_charge,
    'total', o.total, 'advance_amount', o.advance_amount, 'cod_amount', o.cod_amount,
    'courier_company', o.courier_company, 'tracking_number', o.tracking_number,
    'items', coalesce((select jsonb_agg(jsonb_build_object('name', i.product_name, 'size', i.size, 'color', i.color,
                         'quantity', i.quantity, 'line_total', i.line_total, 'image_url', i.image_url) order by i.product_name)
                       from public.order_items i where i.order_id = o.id), '[]'::jsonb),
    'history', coalesce((select jsonb_agg(jsonb_build_object('status', h.to_status, 'note', h.note, 'at', h.created_at) order by h.created_at, h.id)
                         from public.order_status_history h where h.order_id = o.id and h.is_public), '[]'::jsonb));
end
$$;
revoke all on function public.track_order(text, text) from public;
grant execute on function public.track_order(text, text) to anon, authenticated;

-- coupon guessing: any quote that carries a coupon code counts against the visitor.
-- Keeps the Phase 6 advance/COD fields; only the throttle is new.
create or replace function public.quote_order(
  p_items jsonb, p_district text default null, p_coupon text default null, p_phone text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare q jsonb;
begin
  if nullif(trim(coalesce(p_coupon, '')), '') is not null then
    perform public._throttle('coupon:ip:' || public._client_ip(), 60, 600);
  end if;
  q := public._quote(p_items, p_district, p_coupon, auth.uid(), p_phone) - 'coupon_id';
  return q || jsonb_build_object(
           'advance_amount', case when (q ->> 'advance_required')::boolean then (q ->> 'delivery_charge')::numeric else 0 end,
           'cod_amount', (q ->> 'total')::numeric - case when (q ->> 'advance_required')::boolean then (q ->> 'delivery_charge')::numeric else 0 end);
end
$$;
revoke all on function public.quote_order(jsonb, text, text, text) from public;
grant execute on function public.quote_order(jsonb, text, text, text) to anon, authenticated;

-- ---------- 2. anonymous table privileges: only what the public storefront reads ----------
revoke all on all tables in schema public from anon;
grant select on
  public.categories, public.collections, public.products, public.product_collections, public.product_images,
  public.product_variants, public.delivery_zones, public.payment_methods, public.banners, public.hero_slides,
  public.homepage_sections, public.pages, public.menus, public.site_settings, public.blog_posts, public.reviews,
  public.storefront_products, public.public_reviews, public.variant_availability
to anon;

-- ---------- 3. trigger and internal functions are not RPC endpoints ----------
revoke all on function public.audit_content_change() from public, anon, authenticated;
revoke all on function public.create_inventory_for_variant() from public, anon, authenticated;
revoke all on function public.generate_order_number() from public, anon, authenticated;
revoke all on function public.guard_order_changes() from public, anon, authenticated;
revoke all on function public.guard_order_status() from public, anon, authenticated;
revoke all on function public.guard_payment_changes() from public, anon, authenticated;
revoke all on function public.handle_new_user() from public, anon, authenticated;
revoke all on function public.protect_last_super_admin() from public, anon, authenticated;
revoke all on function public.record_order_status() from public, anon, authenticated;
revoke all on function public.set_updated_at() from public, anon, authenticated;
revoke all on function public.stamp_role_grant() from public, anon, authenticated;

-- ===== 20261110000001_guest_proofs.sql =====
-- Guest payment screenshots. A guest may upload a screenshot only into guest/<their order's secret tracking token>/,
-- only while that order is waiting for its advance payment, at most 3 files per order. The bucket itself already
-- limits type (JPG/PNG/WebP) and size (3 MB). Files stay private: only payment staff and the order's owner can read them.

create or replace function public.guest_can_upload_proof(p_path text)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  parts text[] := string_to_array(coalesce(p_path, ''), '/');
begin
  if array_length(parts, 1) is distinct from 3 or parts[1] <> 'guest'
     or parts[2] !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or parts[3] !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$' then
    return false;
  end if;
  if not exists (
    select 1 from public.orders o
     where o.tracking_token = parts[2]::uuid and o.status = 'pending_payment_verification' and o.advance_amount > 0
       and not exists (select 1 from public.payments p where p.order_id = o.id and p.status in ('submitted', 'verified'))) then
    return false;
  end if;
  return (select count(*) from storage.objects where bucket_id = 'payment-proofs' and name like 'guest/' || parts[2] || '/%') < 3;
end
$$;
revoke all on function public.guest_can_upload_proof(text) from public;
grant execute on function public.guest_can_upload_proof(text) to anon, authenticated;

drop policy if exists "guests upload proof with order token" on storage.objects;
create policy "guests upload proof with order token" on storage.objects
  for insert to anon, authenticated
  with check (bucket_id = 'payment-proofs' and public.guest_can_upload_proof(name));

-- submit_payment: same as Phase 6, but a proof may also be a guest file under the caller's own token
create or replace function public.submit_payment(
  p_order_id uuid, p_tracking_token uuid, p_method public.payment_method_code,
  p_sender text, p_txn text, p_proof_path text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  o public.orders;
  v_txn text := upper(trim(coalesce(p_txn, '')));
  v_sender text := trim(coalesce(p_sender, ''));
  v_count integer;
  v_limit integer := coalesce((select (value #>> '{}')::integer from public.site_settings where key = 'payment_resubmission_limit'), 3);
  v_pay public.payments;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found or not coalesce((p_tracking_token is not null and o.tracking_token = p_tracking_token)
                               or (auth.uid() is not null and o.user_id is not null and o.user_id = auth.uid()), false) then
    raise exception 'Order not found.';
  end if;
  if o.status <> 'pending_payment_verification' or o.advance_amount <= 0 then
    raise exception 'This order is not waiting for an advance payment.';
  end if;
  if exists (select 1 from public.payments where order_id = o.id and status in ('submitted', 'verified')) then
    raise exception 'A payment has already been submitted for this order.';
  end if;
  select count(*) into v_count from public.payments where order_id = o.id;
  if v_count >= v_limit then
    raise exception 'You have reached the maximum number of payment attempts. Please contact us.';
  end if;
  if not exists (select 1 from public.payment_methods where code = p_method and is_enabled and merchant_number is not null) then
    raise exception 'This payment method is not available.';
  end if;
  if v_sender !~ '^01[3-9][0-9]{8}$' then raise exception 'Enter the mobile number you sent the money from.'; end if;
  if v_txn !~ '^[A-Z0-9]{6,40}$' then raise exception 'Enter a valid Transaction ID (letters and numbers, 6-40 characters).'; end if;
  if p_proof_path is not null and not (
       length(p_proof_path) <= 200 and position('..' in p_proof_path) = 0 and (
         (auth.uid() is not null and o.user_id = auth.uid() and p_proof_path like auth.uid()::text || '/%')
         or (p_tracking_token is not null and o.tracking_token = p_tracking_token
             and p_proof_path like 'guest/' || p_tracking_token::text || '/%'
             and exists (select 1 from storage.objects where bucket_id = 'payment-proofs' and name = p_proof_path)))) then
    raise exception 'Invalid payment proof.';
  end if;

  begin
    insert into public.payments (order_id, method, amount, status, sender_number, transaction_id, proof_path, attempt, submitted_at)
    values (o.id, p_method, o.advance_amount, 'submitted', v_sender, v_txn, p_proof_path, v_count + 1, now())
    returning * into v_pay;
  exception when unique_violation then
    raise exception 'This Transaction ID has already been used. Please check it and try again.';
  end;
  return jsonb_build_object('payment_id', v_pay.id, 'status', v_pay.status, 'attempt', v_pay.attempt);
end
$$;
revoke all on function public.submit_payment(uuid, uuid, public.payment_method_code, text, text, text) from public;
grant execute on function public.submit_payment(uuid, uuid, public.payment_method_code, text, text, text) to anon, authenticated;
